import { assertEquals, assert } from './assert.js';
import {
  dayKey, dayStart, nextDayStart, weekStartKey, trackWeekKey, trackWeekStart, trackWeekEnd,
  addDays, daysBetween, splitInterval, zoneOffsetMs, wallTimeToEpoch, parseResetTime, isDayKey,
} from '../src/shared/time.js';
// Generated by the Python week_key() from the Track API docs.
import weekKeyFixture from './fixtures/week_keys.json' with { type: 'json' };

const T = (iso) => Date.parse(iso);
const UTC3 = { resetTime: '03:00', timezone: 'UTC' };

Deno.test('day key: default 03:00 UTC reset', () => {
  assertEquals(dayKey(T('2026-10-12T02:59:59Z'), UTC3), '2026-10-11');
  assertEquals(dayKey(T('2026-10-12T03:00:00Z'), UTC3), '2026-10-12');
  assertEquals(dayKey(T('2026-10-12T23:59:59Z'), UTC3), '2026-10-12');
  assertEquals(dayKey(T('2026-10-13T02:59:59.999Z'), UTC3), '2026-10-12');
  // Month / year boundaries
  assertEquals(dayKey(T('2027-01-01T01:00:00Z'), UTC3), '2026-12-31');
  assertEquals(dayKey(T('2024-03-01T02:00:00Z'), UTC3), '2024-02-29');
});

Deno.test('day key: missing settings fall back to 03:00 UTC', () => {
  assertEquals(dayKey(T('2026-10-12T02:00:00Z'), {}), '2026-10-11');
  assertEquals(dayKey(T('2026-10-12T02:00:00Z'), { resetTime: 'nonsense', timezone: 'Not/AZone' }), '2026-10-11');
});

Deno.test('day key: midnight reset and IANA zone', () => {
  const tokyo = { resetTime: '00:00', timezone: 'Asia/Tokyo' };
  assertEquals(dayKey(T('2026-10-11T14:59:59Z'), tokyo), '2026-10-11'); // 23:59:59 JST
  assertEquals(dayKey(T('2026-10-11T15:00:00Z'), tokyo), '2026-10-12'); // 00:00 JST
  const tokyo4 = { resetTime: '04:00', timezone: 'Asia/Tokyo' };
  assertEquals(dayKey(T('2026-10-11T18:59:00Z'), tokyo4), '2026-10-11'); // 03:59 JST on the 12th
  assertEquals(dayKey(T('2026-10-11T19:00:00Z'), tokyo4), '2026-10-12'); // 04:00 JST
});

Deno.test('day key: DST in Europe/London (spring forward and fall back)', () => {
  const ldn = { resetTime: '03:00', timezone: 'Europe/London' };
  // 2026-03-29: clocks go 01:00 GMT → 02:00 BST. 03:00 BST = 02:00 UTC.
  assertEquals(dayKey(T('2026-03-29T01:59:59Z'), ldn), '2026-03-28'); // 02:59:59 BST
  assertEquals(dayKey(T('2026-03-29T02:00:00Z'), ldn), '2026-03-29'); // 03:00 BST
  assertEquals(dayStart('2026-03-29', ldn), T('2026-03-29T02:00:00Z'));
  // 2026-10-25: clocks go 02:00 BST → 01:00 GMT. 03:00 GMT = 03:00 UTC; that day lasts 25 h.
  assertEquals(dayStart('2026-10-25', ldn), T('2026-10-25T03:00:00Z'));
  assertEquals(dayStart('2026-10-24', ldn), T('2026-10-24T02:00:00Z'));
  assertEquals(dayKey(T('2026-10-25T02:59:59Z'), ldn), '2026-10-24');
  assertEquals(dayKey(T('2026-10-25T03:00:00Z'), ldn), '2026-10-25');
  assertEquals(nextDayStart(T('2026-10-24T12:00:00Z'), ldn), T('2026-10-25T03:00:00Z'));
});

Deno.test('day key: DST with a reset inside the skipped hour (America/New_York 02:30)', () => {
  const ny = { resetTime: '02:30', timezone: 'America/New_York' };
  // 2026-03-08: 02:00 EST → 03:00 EDT; 02:30 never happens, so the day starts at 03:00 EDT (07:00Z).
  assertEquals(dayKey(T('2026-03-08T06:59:59Z'), ny), '2026-03-07'); // 01:59:59 EST
  assertEquals(dayKey(T('2026-03-08T07:00:00Z'), ny), '2026-03-08'); // 03:00 EDT
  assertEquals(nextDayStart(T('2026-03-07T12:00:00Z'), ny), T('2026-03-08T07:00:00Z'));
  assertEquals(dayStart('2026-03-08', ny), T('2026-03-08T07:00:00Z'));
});

Deno.test('zone offsets and wall time conversion', () => {
  assertEquals(zoneOffsetMs(T('2026-07-01T00:00:00Z'), 'Asia/Tokyo'), 9 * 3600e3);
  assertEquals(zoneOffsetMs(T('2026-07-01T00:00:00Z'), 'Europe/London'), 3600e3);
  assertEquals(zoneOffsetMs(T('2026-01-01T00:00:00Z'), 'Europe/London'), 0);
  assertEquals(wallTimeToEpoch('2026-07-01', 180, 'Asia/Kolkata'), T('2026-06-30T21:30:00Z'));
});

Deno.test("'local' timezone resolves to the runtime zone", () => {
  const ms = T('2026-10-11T12:00:00Z');
  const zone = Intl.DateTimeFormat().resolvedOptions().timeZone;
  assertEquals(dayKey(ms, { resetTime: '03:00', timezone: 'local' }), dayKey(ms, { resetTime: '03:00', timezone: zone }));
});

Deno.test('week starts', () => {
  // 2026-10-11 is a Sunday.
  assertEquals(weekStartKey('2026-10-11', 1), '2026-10-05'); // Monday weeks
  assertEquals(weekStartKey('2026-10-12', 1), '2026-10-12');
  assertEquals(weekStartKey('2026-10-11', 0), '2026-10-11'); // Sunday weeks
  assertEquals(weekStartKey('2026-10-10', 0), '2026-10-04');
  assertEquals(weekStartKey('2026-10-10', 6), '2026-10-10'); // Saturday weeks
  assertEquals(weekStartKey('2026-10-09', 6), '2026-10-03');
  assertEquals(weekStartKey('2027-01-01', 1), '2026-12-28');
});

Deno.test('Track week key matches the documented example', () => {
  // Week 2026-10-10 runs 2026-10-11T03:00Z → 2026-10-18T03:00Z.
  assertEquals(trackWeekKey(T('2026-10-11T02:59:59Z')), '2026-10-03');
  assertEquals(trackWeekKey(T('2026-10-11T03:00:00Z')), '2026-10-10');
  assertEquals(trackWeekKey(T('2026-10-18T02:59:59Z')), '2026-10-10');
  assertEquals(trackWeekKey(T('2026-10-18T03:00:00Z')), '2026-10-17');
  assertEquals(trackWeekStart('2026-10-10'), T('2026-10-11T03:00:00Z'));
  assertEquals(trackWeekEnd('2026-10-10'), T('2026-10-18T03:00:00Z'));
});

Deno.test('Track week key matches the Python week_key on 409 instants', () => {
  const { cases } = weekKeyFixture;
  assert(cases.length > 400);
  for (const [ms, key] of cases) assertEquals(trackWeekKey(ms), key, `at ${new Date(ms).toISOString()}`);
});

Deno.test('key arithmetic', () => {
  assertEquals(addDays('2026-02-28', 1), '2026-03-01');
  assertEquals(addDays('2024-02-28', 1), '2024-02-29');
  assertEquals(addDays('2026-01-01', -1), '2025-12-31');
  assertEquals(daysBetween('2026-06-30', '2026-07-01'), 1);
  assertEquals(daysBetween('2026-03-01', '2026-03-31'), 30);
  assert(isDayKey('2026-02-28'));
  assert(!isDayKey('2026-02-30'));
  assert(!isDayKey('2026-2-3'));
  assertEquals(parseResetTime('3:05'), 185);
  assertEquals(parseResetTime('24:00'), null);
});

Deno.test('splitInterval cuts at the user day and the Track week', () => {
  // Saturday 2026-10-10 23:00Z → Sunday 2026-10-11 04:00Z: the user day changes at 03:00Z, and
  // so does the Track week.
  const parts = splitInterval(T('2026-10-11T02:00:00Z'), T('2026-10-11T04:00:00Z'), UTC3);
  assertEquals(parts.map((p) => [new Date(p.start).toISOString(), p.dayKey, p.trackWeek]), [
    ['2026-10-11T02:00:00.000Z', '2026-10-10', '2026-10-03'],
    ['2026-10-11T03:00:00.000Z', '2026-10-11', '2026-10-10'],
  ]);
  // Midnight-JST reset: day changes at 15:00Z, Track week doesn't.
  const jst = { resetTime: '00:00', timezone: 'Asia/Tokyo' };
  const p2 = splitInterval(T('2026-10-12T14:59:00Z'), T('2026-10-12T15:01:00Z'), jst);
  assertEquals(p2.map((p) => [p.end - p.start, p.dayKey, p.trackWeek]), [
    [60_000, '2026-10-12', '2026-10-10'],
    [60_000, '2026-10-13', '2026-10-10'],
  ]);
  // Within one day: a single piece.
  assertEquals(splitInterval(T('2026-10-12T10:00:00Z'), T('2026-10-12T10:00:05Z'), UTC3).length, 1);
});
